def f(n):
    """Calculates the largest odd divisor of n."""
    if n <= 0:
        raise ValueError("n must be a positive integer")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(v, u):
    """Checks if the condition holds for given v and u."""
    if v <= 0 or u <= 0:
        return False

    # The condition is: f(u+v+i) - f(u+i) is a multiple of 4 for i=0, ..., v-1
    for i in range(v):
        term1 = f(u + i)
        term2 = f(u + i + v)
        difference = term2 - term1
        if difference % 4 != 0:
            return False
    return True

V_to_test = [13, 15, 17]
U_to_test = [1, 2, 3, 4]
results = {}

for v in V_to_test:
    found_u = None
    for u in U_to_test:
        if check_condition(v, u):
            found_u = u
            break # Found the smallest u

    if found_u is not None:
        results[v] = found_u

print(f"Testing V = {V_to_test}")
print(f"Found results (V: smallest U): {results}")
